const fs = require("fs");
const path = require("path");
const nunjucks = require("nunjucks");

const templatesDir = path.join(__dirname, "..", "src", "templates");
const outputFile = path.join(__dirname, "..", "src", "templates-bundle.js");

const assignments = [];
const files = fs.readdirSync(templatesDir).filter((f) => f.endsWith(".njk"));

for (const file of files) {
  const name = file.replace(/\.njk$/, "");
  const src = fs.readFileSync(path.join(templatesDir, file), "utf8");

  // Precompile the template with Nunjucks (Node build). The default output
  // wraps the compiled function in an IIFE that assigns to
  // window.nunjucksPrecompiled[name]. We rewrite that assignment to
  // populate our ES-module `templates` object so the Worker runtime
  // (nunjucks-slim) can render it without using eval/new Function.
  const compiled = nunjucks.precompileString(src, { name }).trim();
  const transformed = compiled
    .replace(
      /^\(function\(\)\s*\{\(window\.nunjucksPrecompiled\s*=\s*window\.nunjucksPrecompiled\s*\|\|\s*\{\}\)\["[^"]+"\]\s*=\s*/,
      `templates[${JSON.stringify(name)}] = `
    )
    .replace(/\}\)\(\);$/, ";");

  assignments.push(transformed);
}

const output = `// Auto-generated by scripts/bundle-templates.js
// Do not edit this file directly.

export const templates = {};
${assignments.join("\n")}
`;

fs.writeFileSync(outputFile, output);
console.log(`Bundled ${files.length} templates into ${outputFile}`);
